1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: { op: string; items: { type: string }[] }[];
4	};
5	
6	export type ScenarioResult = {
7	  results: { premium: number }[];
8	};
9	
10	const PROCESSING_FEE = 5;
11	
12	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
13	
14	const BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	};
19	
20	// Percentages are applied as integer percent points — `base * 1.1` yields
21	// 110.00000000000001 for a sword and breaks the ceil.
22	const applyPercent = (amount: number, percent: number): number =>
23	  (amount * percent) / 100;
24	
25	const quote = (items: { type: string }[]): number => {
26	  const basePremium = items.reduce(
27	    (sum, item) => sum + BASE_PREMIUMS[item.type],
28	    0,
29	  );
30	
31	  const firstInsuranceSurcharge = applyPercent(
32	    basePremium,
33	    FIRST_INSURANCE_SURCHARGE_PERCENT,
34	  );
35	
36	  return Math.ceil(basePremium + firstInsuranceSurcharge) + PROCESSING_FEE;
37	};
38	
39	export const runScenario = (scenario: Scenario): ScenarioResult => ({
40	  results: scenario.steps.map((step) => ({ premium: quote(step.items) })),
41	});
